Test.Description:
      -- SetupConfig: {}
      create transformer on CK.sTest
      as
      begin
	      in single statement {set @CGroup = cursor}
        begin
	        in first part {select}
	        begin
		        inject "not exists(select * from CK.tZone where ZoneId = a.GroupId) and " before single {g.ZoneId = @ZoneId};
	        end
        end
      end
